 13→// TaskHookInput represents the JSON input from PreToolUse[Task] hook
 14→type TaskHookInput struct {
 15→	SessionID      string          `json:"session_id"`
 16→	TranscriptPath string          `json:"transcript_path"`
 17→	ToolUseID      string          `json:"tool_use_id"`
 18→	ToolInput      json.RawMessage `json:"tool_input"`
 19→}
