 21→// postTaskHookInputRaw is the raw JSON structure from PostToolUse[Task] hook
 22→type postTaskHookInputRaw struct {
 23→	SessionID      string          `json:"session_id"`
 24→	TranscriptPath string          `json:"transcript_path"`
 25→	ToolUseID      string          `json:"tool_use_id"`
 26→	ToolInput      json.RawMessage `json:"tool_input"`
 27→	ToolResponse   struct {
 28→		AgentID string `json:"agentId"`
 29→	} `json:"tool_response"`
 30→}
