 32→// PostTaskHookInput represents the parsed input from PostToolUse[Task] hook
 33→type PostTaskHookInput struct {
 34→	TaskHookInput
 35→
 36→	AgentID   string          // Extracted from tool_response.agentId
 37→	ToolInput json.RawMessage // Raw tool input for reference
 38→}
