func TestInstallHooks_PermissionsDeny_PreservesUnknownFields(t *testing.T) { //nolint:tparallel // Uses t.Chdir which prevents t.Parallel
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	// Create settings.json with unknown permission fields like "ask"
	writeFactorySettingsFile(t, tempDir, `{
  "permissions": {
    "allow": ["Read(**)"],
    "ask": ["Write(**)", "Bash(*)"],
    "customField": {"nested": "value"}
  }
}`)

