 90→// CalculateTokenUsage calculates token usage from a Factory AI Droid transcript.
 91→// Due to streaming, multiple transcript rows may share the same message.id.
 92→// We deduplicate by taking the row with the highest output_tokens for each message.id.
 93→func CalculateTokenUsage(transcriptLines []TranscriptLine) *agent.TokenUsage {
 94→	// Map from message.id to the usage with highest output_tokens
 95→	usageByMessageID := make(map[string]messageUsage)
 96→
 97→	for _, line := range transcriptLines {
 98→		if line.Type != "assistant" {
 99→			continue
100→		}
101→
102→		var msg messageWithUsage
103→		if err := json.Unmarshal(line.Message, &msg); err != nil {
104→			continue
105→		}
106→
107→		if msg.ID == "" {
108→			continue
109→		}
110→
111→		// Keep the entry with highest output_tokens (final streaming state)
112→		existing, exists := usageByMessageID[msg.ID]
113→		if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
114→			usageByMessageID[msg.ID] = msg.Usage
115→		}
116→	}
117→
118→	// Sum up all unique messages
119→	usage := &agent.TokenUsage{
120→		APICallCount: len(usageByMessageID),
121→	}
122→	for _, u := range usageByMessageID {
123→		usage.InputTokens += u.InputTokens
124→		usage.CacheCreationTokens += u.CacheCreationInputTokens
125→		usage.CacheReadTokens += u.CacheReadInputTokens
126→		usage.OutputTokens += u.OutputTokens
127→	}
128→
129→	return usage
130→}
131→
132→// CalculateTokenUsageFromFile calculates token usage from a transcript file.
133→// If startLine > 0, only considers lines from startLine onwards.
134→func CalculateTokenUsageFromFile(path string, startLine int) (*agent.TokenUsage, error) {
135→	if path == "" {
136→		return &agent.TokenUsage{}, nil
137→	}
138→
139→	lines, _, err := transcript.ParseFromFileAtLine(path, startLine)
140→	if err != nil {
141→		return nil, err //nolint:wrapcheck // caller adds context
142→	}
143→
144→	return CalculateTokenUsage(lines), nil
145→}
146→
147→// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
148→// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
149→// Returns a map of agentID -> toolUseID for all spawned agents.
150→func ExtractSpawnedAgentIDs(transcriptLines []TranscriptLine) map[string]string {
151→	agentIDs := make(map[string]string)
152→
153→	for _, line := range transcriptLines {
154→		if line.Type != "user" {
155→			continue
156→		}
157→
158→		// Parse as array of content blocks (tool results)
159→		var contentBlocks []struct {
160→			Type      string          `json:"type"`
161→			ToolUseID string          `json:"tool_use_id"`
162→			Content   json.RawMessage `json:"content"`
163→		}
164→
165→		var msg struct {
166→			Content json.RawMessage `json:"content"`
167→		}
168→		if err := json.Unmarshal(line.Message, &msg); err != nil {
169→			continue
170→		}
171→
172→		if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
173→			continue
174→		}
175→
176→		for _, block := range contentBlocks {
177→			if block.Type != "tool_result" {
178→				continue
179→			}
180→
181→			// Content can be a string or array of text blocks
182→			var textContent string
183→
184→			// Try as array of text blocks first
185→			var textBlocks []struct {
186→				Type string `json:"type"`
187→				Text string `json:"text"`
188→			}
189→			if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
190→				var sb strings.Builder
191→				for _, tb := range textBlocks {
192→					if tb.Type == "text" {
193→						sb.WriteString(tb.Text + "\n")
194→					}
195→				}
196→				textContent += sb.String()
197→			} else {
198→				// Try as plain string
199→				var str string
200→				if err := json.Unmarshal(block.Content, &str); err == nil {
201→					textContent = str
202→				}
203→			}
204→
205→			// Look for agentId in the text
206→			if agentID := extractAgentIDFromText(textContent); agentID != "" {
207→				agentIDs[agentID] = block.ToolUseID
208→			}
209→		}
210→	}
211→
212→	return agentIDs
213→}
214→
215→// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
216→func extractAgentIDFromText(text string) string {
217→	const prefix = "agentId: "
218→	idx := strings.Index(text, prefix)
219→	if idx == -1 {
220→		return ""
221→	}
222→
223→	// Extract the ID (alphanumeric characters after the prefix)
224→	start := idx + len(prefix)
225→	end := start
226→	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
227→		text[end] >= 'A' && text[end] <= 'Z' ||
228→		text[end] >= '0' && text[end] <= '9') {
229→		end++
230→	}
231→
232→	if end > start {
233→		return text[start:end]
234→	}
235→	return ""
236→}
237→
238→// CalculateTotalTokenUsageFromTranscript calculates token usage for a turn, including subagents.
239→// It parses the main transcript from startLine, extracts spawned agent IDs,
240→// and calculates their token usage from transcripts in subagentsDir.
241→func CalculateTotalTokenUsageFromTranscript(transcriptPath string, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
242→	if transcriptPath == "" {
243→		return &agent.TokenUsage{}, nil
244→	}
245→
246→	// Parse transcript once
247→	parsed, _, err := transcript.ParseFromFileAtLine(transcriptPath, startLine)
248→	if err != nil {
249→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
250→	}
251→
252→	// Calculate token usage from parsed transcript
253→	mainUsage := CalculateTokenUsage(parsed)
254→
255→	// Extract spawned agent IDs from the same parsed transcript
256→	agentIDs := ExtractSpawnedAgentIDs(parsed)
257→
258→	// Calculate subagent token usage
259→	if len(agentIDs) > 0 {
260→		subagentUsage := &agent.TokenUsage{}
261→		for agentID := range agentIDs {
262→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
263→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
264→			if err != nil {
265→				// Agent transcript may not exist yet or may have been cleaned up
266→				continue
267→			}
268→			subagentUsage.InputTokens += agentUsage.InputTokens
269→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
270→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
271→			subagentUsage.OutputTokens += agentUsage.OutputTokens
272→			subagentUsage.APICallCount += agentUsage.APICallCount
273→		}
274→		if subagentUsage.APICallCount > 0 {
275→			mainUsage.SubagentTokens = subagentUsage
276→		}
277→	}
278→
279→	return mainUsage, nil
280→}
281→
282→// ExtractAllModifiedFilesFromTranscript extracts files modified by both the main agent and
283→// any subagents spawned via the Task tool. It parses the main transcript from
284→// startLine, collects modified files from the main agent, then reads each
285→// subagent's transcript from subagentsDir to collect their modified files too.
286→// The result is a deduplicated list of all modified file paths.
287→func ExtractAllModifiedFilesFromTranscript(transcriptPath string, startLine int, subagentsDir string) ([]string, error) {
288→	if transcriptPath == "" {
289→		return nil, nil
290→	}
291→
292→	// Parse main transcript once
293→	parsed, _, err := transcript.ParseFromFileAtLine(transcriptPath, startLine)
294→	if err != nil {
295→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
296→	}
297→
298→	// Collect modified files from main agent
299→	fileSet := make(map[string]bool)
300→	var files []string
301→	for _, f := range ExtractModifiedFiles(parsed) {
302→		if !fileSet[f] {
303→			fileSet[f] = true
304→			files = append(files, f)
305→		}
306→	}
307→
308→	// Find spawned subagents and collect their modified files
309→	agentIDs := ExtractSpawnedAgentIDs(parsed)
310→	for agentID := range agentIDs {
311→		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
312→		agentLines, _, agentErr := transcript.ParseFromFileAtLine(agentPath, 0)
313→		if agentErr != nil {
314→			// Subagent transcript may not exist yet or may have been cleaned up
315→			continue
316→		}
317→		for _, f := range ExtractModifiedFiles(agentLines) {
318→			if !fileSet[f] {
319→				fileSet[f] = true
320→				files = append(files, f)
321→			}
322→		}
323→	}
324→
325→	return files, nil
326→}
