153→func TestCalculateTokenUsage_StreamingDeduplication(t *testing.T) {
154→	t.Parallel()
155→
156→	// Simulate streaming: multiple rows with same message ID, increasing output_tokens
157→	lines := []TranscriptLine{
158→		{
159→			Type: "assistant",
