163→				"usage": map[string]int{
164→					"input_tokens":                10,
165→					"cache_creation_input_tokens": 100,
166→					"cache_read_input_tokens":     50,
167→					"output_tokens":               1, // First streaming chunk
168→				},
169→			}),
170→		},
171→		{
172→			Type: "assistant",
173→			UUID: "asst-2",
174→			Message: mustMarshal(t, map[string]interface{}{
175→				"id": "msg_001", // Same message ID
176→				"usage": map[string]int{
177→					"input_tokens":                10,
178→					"cache_creation_input_tokens": 100,
179→					"cache_read_input_tokens":     50,
180→					"output_tokens":               5, // More output
181→				},
182→			}),
183→		},
184→		{
185→			Type: "assistant",
186→			UUID: "asst-3",
187→			Message: mustMarshal(t, map[string]interface{}{
188→				"id": "msg_001", // Same message ID
189→				"usage": map[string]int{
190→					"input_tokens":                10,
191→					"cache_creation_input_tokens": 100,
192→					"cache_read_input_tokens":     50,
193→					"output_tokens":               20, // Final output
194→				},
195→			}),
196→		},
197→	}
