428→	// 1: assistant response 1 (100/50 tokens)
429→	// 2: user message 2
430→	// 3: assistant response 2 (200/100 tokens)
431→	// 4: user message 3
432→	// 5: assistant response 3 (300/150 tokens)
433→
434→	transcriptContent := []byte(
435→		`{"type":"user","uuid":"u1","message":{"content":"first prompt"}}` + "\n" +
436→			`{"type":"assistant","uuid":"a1","message":{"id":"m1","usage":{"input_tokens":100,"output_tokens":50}}}` + "\n" +
