 56→// IsEnabled returns whether Entire is currently enabled.
 57→// Returns true by default if settings cannot be loaded.
 58→func IsEnabled() (bool, error) {
 59→	s, err := settings.Load()
 60→	if err != nil {
 61→		return true, err //nolint:wrapcheck // already present in codebase
 62→	}
 63→	return s.Enabled, nil
 64→}
