 66→// GetStrategy returns the configured strategy instance.
 67→// Falls back to default if the configured strategy is not found.
 68→//
 69→
 70→func GetStrategy() strategy.Strategy {
 71→	s, err := settings.Load()
 72→	if err != nil {
 73→		// Fall back to default on error
 74→		logging.Info(context.Background(), "falling back to default strategy - failed to load settings",
 75→			slog.String("error", err.Error()))
 76→		return strategy.Default()
 77→	}
 78→
 79→	strat, err := strategy.Get(s.Strategy)
 80→	if err != nil {
 81→		// Fall back to default if strategy not found
 82→		logging.Info(context.Background(), "falling back to default strategy - configured strategy not found",
 83→			slog.String("configured", s.Strategy),
 84→			slog.String("error", err.Error()))
 85→		return strategy.Default()
 86→	}
 87→
 88→	return strat
 89→}
