 91→// GetLogLevel returns the configured log level from settings.
 92→// Returns empty string if not configured (caller should use default).
 93→// Note: ENTIRE_LOG_LEVEL env var takes precedence; check it first.
 94→func GetLogLevel() string {
 95→	s, err := settings.Load()
 96→	if err != nil {
 97→		return ""
 98→	}
 99→	return s.LogLevel
