102→// GetAgentsWithHooksInstalled returns names of agents that have hooks installed.
103→func GetAgentsWithHooksInstalled() []agent.AgentName {
104→	var installed []agent.AgentName
105→	for _, name := range agent.List() {
106→		ag, err := agent.Get(name)
107→		if err != nil {
108→			continue
109→		}
110→		if hs, ok := ag.(agent.HookSupport); ok && hs.AreHooksInstalled() {
111→			installed = append(installed, name)
112→		}
113→	}
114→	return installed
115→}
