117→// JoinAgentNames joins agent names into a comma-separated string.
118→func JoinAgentNames(names []agent.AgentName) string {
119→	strs := make([]string, len(names))
120→	for i, n := range names {
121→		strs[i] = string(n)
122→	}
123→	return strings.Join(strs, ",")
124→}
