 32→// ParseHookEvent translates a Factory AI Droid hook into a normalized lifecycle Event.
 33→// Returns nil if the hook has no lifecycle significance.
 34→func (f *FactoryAIDroidAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
 35→	switch hookName {
 36→	case HookNameSessionStart:
 37→		return f.parseSessionStart(stdin)
 38→	case HookNameUserPromptSubmit:
 39→		return f.parseTurnStart(stdin)
 40→	case HookNameStop:
 41→		return f.parseTurnEnd(stdin)
 42→	case HookNameSessionEnd:
 43→		return f.parseSessionEnd(stdin)
 44→	case HookNamePreToolUse:
 45→		return f.parseSubagentStart(stdin)
 46→	case HookNamePostToolUse:
 47→		return f.parseSubagentEnd(stdin)
 48→	case HookNamePreCompact:
 49→		return f.parseCompaction(stdin)
 50→	case HookNameSubagentStop, HookNameNotification:
 51→		// Acknowledged hooks with no lifecycle action
 52→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 53→	default:
 54→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 55→	}
 56→}
