 58→// --- TranscriptAnalyzer ---
 59→
 60→// GetTranscriptPosition returns the current line count of the JSONL transcript.
 61→func (f *FactoryAIDroidAgent) GetTranscriptPosition(path string) (int, error) {
 62→	_, pos, err := transcript.ParseFromFileAtLine(path, 0)
 63→	if err != nil {
 64→		return 0, err //nolint:wrapcheck // caller adds context
 65→	}
 66→	return pos, nil
 67→}
 68→
 69→// ExtractModifiedFilesFromOffset extracts files modified since a given line offset.
 70→func (f *FactoryAIDroidAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
 71→	lines, currentPos, err := transcript.ParseFromFileAtLine(path, startOffset)
 72→	if err != nil {
 73→		return nil, 0, fmt.Errorf("failed to parse transcript: %w", err)
 74→	}
 75→	files := ExtractModifiedFiles(lines)
 76→	return files, currentPos, nil
 77→}
 78→
 79→// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
 80→func (f *FactoryAIDroidAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
 81→	lines, _, err := transcript.ParseFromFileAtLine(sessionRef, fromOffset)
 82→	if err != nil {
 83→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
 84→	}
 85→
 86→	var prompts []string
 87→	for i := range lines {
 88→		if lines[i].Type != transcript.TypeUser {
 89→			continue
 90→		}
 91→		content := transcript.ExtractUserContent(lines[i].Message)
 92→		if content != "" {
 93→			prompts = append(prompts, textutil.StripIDEContextTags(content))
 94→		}
 95→	}
 96→	return prompts, nil
 97→}
 98→
 99→// ExtractSummary extracts the last assistant message as a session summary.
100→func (f *FactoryAIDroidAgent) ExtractSummary(sessionRef string) (string, error) {
101→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
102→	if err != nil {
103→		return "", fmt.Errorf("failed to read transcript: %w", err)
104→	}
105→
106→	lines, parseErr := transcript.ParseFromBytes(data)
107→	if parseErr != nil {
108→		return "", fmt.Errorf("failed to parse transcript: %w", parseErr)
109→	}
110→
111→	for i := len(lines) - 1; i >= 0; i-- {
112→		if lines[i].Type != transcript.TypeAssistant {
113→			continue
114→		}
115→		var msg transcript.AssistantMessage
116→		if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
117→			continue
118→		}
119→		for _, block := range msg.Content {
120→			if block.Type == transcript.ContentTypeText && block.Text != "" {
121→				return block.Text, nil
122→			}
123→		}
124→	}
125→	return "", nil
126→}
