128→// --- TranscriptPreparer ---
129→
130→// PrepareTranscript waits for Factory Droid's async transcript flush to complete.
131→func (f *FactoryAIDroidAgent) PrepareTranscript(sessionRef string) error {
132→	waitForTranscriptFlush(sessionRef, time.Now())
133→	return nil
