 78→// CalculateTokenUsage calculates token usage from a Factory AI Droid transcript.
 79→// Due to streaming, multiple transcript rows may share the same message.id.
 80→// We deduplicate by taking the row with the highest output_tokens for each message.id.
 81→func CalculateTokenUsage(transcriptLines []TranscriptLine) *agent.TokenUsage {
 82→	// Map from message.id to the usage with highest output_tokens
 83→	usageByMessageID := make(map[string]messageUsage)
 84→
 85→	for _, line := range transcriptLines {
 86→		if line.Type != "assistant" {
 87→			continue
 88→		}
 89→
 90→		var msg messageWithUsage
 91→		if err := json.Unmarshal(line.Message, &msg); err != nil {
 92→			continue
 93→		}
 94→
 95→		if msg.ID == "" {
 96→			continue
 97→		}
 98→
 99→		// Keep the entry with highest output_tokens (final streaming state)
100→		existing, exists := usageByMessageID[msg.ID]
101→		if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
102→			usageByMessageID[msg.ID] = msg.Usage
103→		}
104→	}
105→
106→	// Sum up all unique messages
107→	usage := &agent.TokenUsage{
108→		APICallCount: len(usageByMessageID),
109→	}
110→	for _, u := range usageByMessageID {
111→		usage.InputTokens += u.InputTokens
112→		usage.CacheCreationTokens += u.CacheCreationInputTokens
113→		usage.CacheReadTokens += u.CacheReadInputTokens
114→		usage.OutputTokens += u.OutputTokens
115→	}
116→
117→	return usage
118→}
