120→// CalculateTokenUsageFromFile calculates token usage from a transcript file.
121→// If startLine > 0, only considers lines from startLine onwards.
122→func CalculateTokenUsageFromFile(path string, startLine int) (*agent.TokenUsage, error) {
123→	if path == "" {
124→		return &agent.TokenUsage{}, nil
125→	}
126→
127→	lines, _, err := transcript.ParseFromFileAtLine(path, startLine)
128→	if err != nil {
129→		return nil, err //nolint:wrapcheck // caller adds context
130→	}
131→
132→	return CalculateTokenUsage(lines), nil
133→}
