135→// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
136→// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
137→// Returns a map of agentID -> toolUseID for all spawned agents.
138→func ExtractSpawnedAgentIDs(transcriptLines []TranscriptLine) map[string]string {
139→	agentIDs := make(map[string]string)
140→
141→	for _, line := range transcriptLines {
142→		if line.Type != "user" {
143→			continue
144→		}
145→
146→		// Parse as array of content blocks (tool results)
147→		var contentBlocks []struct {
148→			Type      string          `json:"type"`
149→			ToolUseID string          `json:"tool_use_id"`
150→			Content   json.RawMessage `json:"content"`
151→		}
152→
153→		var msg struct {
154→			Content json.RawMessage `json:"content"`
155→		}
156→		if err := json.Unmarshal(line.Message, &msg); err != nil {
157→			continue
158→		}
159→
160→		if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
161→			continue
162→		}
163→
164→		for _, block := range contentBlocks {
165→			if block.Type != "tool_result" {
166→				continue
167→			}
168→
169→			// Content can be a string or array of text blocks
170→			var textContent string
171→
172→			// Try as array of text blocks first
173→			var textBlocks []struct {
174→				Type string `json:"type"`
175→				Text string `json:"text"`
176→			}
177→			if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
178→				var sb strings.Builder
179→				for _, tb := range textBlocks {
180→					if tb.Type == "text" {
181→						sb.WriteString(tb.Text + "\n")
182→					}
183→				}
184→				textContent = sb.String()
185→			} else {
186→				// Try as plain string
187→				var str string
188→				if err := json.Unmarshal(block.Content, &str); err == nil {
189→					textContent = str
190→				}
191→			}
192→
193→			// Look for agentId in the text
194→			if agentID := extractAgentIDFromText(textContent); agentID != "" {
195→				agentIDs[agentID] = block.ToolUseID
196→			}
197→		}
198→	}
199→
200→	return agentIDs
201→}
