203→// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
204→func extractAgentIDFromText(text string) string {
205→	const prefix = "agentId: "
206→	idx := strings.Index(text, prefix)
207→	if idx == -1 {
208→		return ""
209→	}
210→
211→	// Extract the ID (alphanumeric characters after the prefix)
212→	start := idx + len(prefix)
213→	end := start
214→	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
215→		text[end] >= 'A' && text[end] <= 'Z' ||
216→		text[end] >= '0' && text[end] <= '9') {
217→		end++
218→	}
219→
220→	if end > start {
221→		return text[start:end]
222→	}
223→	return ""
224→}
