226→// CalculateTotalTokenUsageFromTranscript calculates token usage for a turn, including subagents.
227→// It parses the main transcript from startLine, extracts spawned agent IDs,
228→// and calculates their token usage from transcripts in subagentsDir.
229→func CalculateTotalTokenUsageFromTranscript(transcriptPath string, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
230→	if transcriptPath == "" {
231→		return &agent.TokenUsage{}, nil
232→	}
233→
234→	// Parse transcript once
235→	parsed, _, err := transcript.ParseFromFileAtLine(transcriptPath, startLine)
236→	if err != nil {
237→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
238→	}
239→
240→	// Calculate token usage from parsed transcript
241→	mainUsage := CalculateTokenUsage(parsed)
242→
243→	// Extract spawned agent IDs from the same parsed transcript
244→	agentIDs := ExtractSpawnedAgentIDs(parsed)
245→
246→	// Calculate subagent token usage
247→	if len(agentIDs) > 0 {
248→		subagentUsage := &agent.TokenUsage{}
249→		for agentID := range agentIDs {
250→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
251→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
252→			if err != nil {
253→				// Agent transcript may not exist yet or may have been cleaned up
254→				continue
255→			}
256→			subagentUsage.InputTokens += agentUsage.InputTokens
257→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
258→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
259→			subagentUsage.OutputTokens += agentUsage.OutputTokens
260→			subagentUsage.APICallCount += agentUsage.APICallCount
261→		}
262→		if subagentUsage.APICallCount > 0 {
263→			mainUsage.SubagentTokens = subagentUsage
264→		}
265→	}
266→
267→	return mainUsage, nil
268→}
