270→// ExtractAllModifiedFilesFromTranscript extracts files modified by both the main agent and
271→// any subagents spawned via the Task tool. It parses the main transcript from
272→// startLine, collects modified files from the main agent, then reads each
273→// subagent's transcript from subagentsDir to collect their modified files too.
274→// The result is a deduplicated list of all modified file paths.
275→func ExtractAllModifiedFilesFromTranscript(transcriptPath string, startLine int, subagentsDir string) ([]string, error) {
276→	if transcriptPath == "" {
277→		return nil, nil
278→	}
279→
280→	// Parse main transcript once
281→	parsed, _, err := transcript.ParseFromFileAtLine(transcriptPath, startLine)
282→	if err != nil {
283→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
284→	}
285→
286→	// Collect modified files from main agent
287→	fileSet := make(map[string]bool)
288→	var files []string
289→	for _, f := range ExtractModifiedFiles(parsed) {
290→		if !fileSet[f] {
291→			fileSet[f] = true
292→			files = append(files, f)
293→		}
294→	}
295→
296→	// Find spawned subagents and collect their modified files
297→	agentIDs := ExtractSpawnedAgentIDs(parsed)
298→	for agentID := range agentIDs {
299→		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
300→		agentLines, _, agentErr := transcript.ParseFromFileAtLine(agentPath, 0)
301→		if agentErr != nil {
302→			// Subagent transcript may not exist yet or may have been cleaned up
303→			continue
304→		}
305→		for _, f := range ExtractModifiedFiles(agentLines) {
306→			if !fileSet[f] {
307→				fileSet[f] = true
308→				files = append(files, f)
309→			}
310→		}
311→	}
312→
313→	return files, nil
314→}
